    private readonly ActorAnimationOperations _animation=new();private readonly ActorTextSettingsOperations _text=new();private readonly ActorImageGeneratorOperations _images=new();private readonly ActorShaderTimeOperations _shaderTime=new();
    private static Node2D Visual(Node3D owner)=>owner.Get("visual").As<Node2D>();private static Resource Actor(Node3D owner)=>owner.Get("actor").As<Resource>();private static Variant Get(Settings v,string key,Variant fallback=default)=>v.GetValueOrDefault(key,fallback);
