        owner.AddToGroup("actor_shader_runtimes");var layer=new CanvasLayer{Layer=10};owner.Set("canvas_layer",layer);owner.AddChild(layer);var anchor=owner.Get("anchor").As<Node2D>();layer.AddChild(anchor);var visual=Visual(owner);anchor.AddChild(visual);var label=owner.Get("label").As<Label>();visual.AddChild(label);label.UseParentMaterial=true;label.HorizontalAlignment=HorizontalAlignment.Center;label.VerticalAlignment=VerticalAlignment.Center;label.AutowrapMode=TextServer.AutowrapMode.WordSmart;label.MouseFilter=Control.MouseFilterEnum.Ignore;label.Visible=Actor(owner).Get("type_id").AsString()=="text_2d";if(Actor(owner).Get("type_id").AsString()=="particles_2d"){var particles=new GpuParticles2D();particles.Set("use_fixed_seed",true);particles.Set("seed",GD.Hash(Actor(owner).Get("id").AsString())&0x7fffffff);owner.Set("particles_2d",particles);var process=new ParticleProcessMaterial();process.Set("particle_flag_disable_z",true);owner.Set("particle_material_2d",process);particles.ProcessMaterial=process;var gradient=new Gradient{Colors=new[]{Colors.White,new Color(1,1,1,0)}};var texture=new GradientTexture2D{Width=32,Height=32,Gradient=gradient,FillFrom=new Vector2(.5f,.5f),FillTo=new Vector2(1,.5f)};texture.Set("fill",1);particles.Texture=texture;anchor.AddChild(particles);}
    }
