        owner.Set("_time",time);owner.Set("_values",values);var visual=Visual(owner);var dimensions=Get(values,"size",new Vector2(400,240)).AsVector2().Abs().Max(Vector2.One);visual.Set("dimensions",dimensions);switch(Actor(owner).Get("type_id").AsString()){case "text_2d":var label=owner.Get("label").As<Label>();label.Text=Get(values,"text","Text").AsString();label.Position=-dimensions/2;label.Size=dimensions;var settings=_text.values(Get(values,"text_settings"));long signature=GD.Hash(settings);if(signature!=owner.Get("_text_signature").AsInt64()){owner.Set("_text_signature",signature);_text.apply_label(label,settings);}break;case "basic_shape_2d":visual.Set("shape",Get(values,"shape",0));visual.Set("fill",Get(values,"color",Colors.White));visual.Set("outline",Get(values,"outline_color",Colors.White));visual.Set("width",Math.Max(0,Get(values,"outline_size",0.0).AsDouble()));break;case "image_2d":var candidate=Get(values,"image_path");Resource? resource=candidate.VariantType==Variant.Type.Object&&candidate.AsGodotObject() is Resource reference&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd")?_animation.resolve_reference(reference):null;string imageSignature=resource!=null?GD.Hash(resource.Get("values")).ToString():"empty";if(imageSignature!=owner.Get("_image_signature").AsString()){owner.Set("_image_signature",imageSignature);var imageTexture=_images.texture_for_object(resource);visual.Set("texture",imageTexture!=null?Variant.From(imageTexture):default);}break;case "video_2d":string path=Get(values,"video","").AsString();if(path!=owner.Get("_video_path").AsString()){owner.Set("_video_path",path);visual.Set("texture",default(Variant));}var texture=GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs").Call("frame",path,time,true).As<Texture2D>();if(texture!=null)visual.Set("texture",texture);break;case "line_2d":visual.Set("shape",5);visual.Set("fill",Get(values,"color",Colors.White));visual.Set("width",Math.Max(.1,Get(values,"width",4.0).AsDouble()));break;case "particles_2d":apply_particles_2d(owner,values);break;}apply_canvas_material(owner,Get(values,"material"));visual.QueueRedraw();
    }
    public void process(Node3D owner,double delta){var values=owner.Get("_values").AsGodotDictionary();if(owner.Get("active").AsBool()&&Actor(owner).Get("type_id").AsString()=="video_2d"&&values.Count>0)evaluate(owner,owner.Get("_time").AsDouble(),values);}
